/* No.005 */
(() => {
const TEX = {"eFrontBase": "front.jpg", "eFiber": "sheen.png", "eMask": "glitter.png", "eBack": "back.jpg"};
const BOW_OUT = [[-0.7324, 0.6523], [-0.7617, 0.6172], [-0.8379, 0.5117], [-0.8789, 0.4434], [-0.9102, 0.3809], [-0.9355, 0.3145], [-0.957, 0.2461], [-0.9805, 0.1445], [-0.9922, 0.0781], [-1.0, -0.0078], [-1.0, -0.1094], [-0.9902, -0.2266], [-0.9766, -0.3125], [-0.9609, -0.373], [-0.9434, -0.418], [-0.916, -0.4512], [-0.9023, -0.459], [-0.8809, -0.4648], [-0.8047, -0.4668], [-0.4727, -0.4414], [-0.2598, -0.4141], [-0.0684, -0.377], [0.002, -0.3672], [0.0254, -0.373], [0.0488, -0.3867], [0.1172, -0.4492], [0.2109, -0.5449], [0.2617, -0.5918], [0.3457, -0.6582], [0.4004, -0.6875], [0.457, -0.707], [0.4961, -0.7148], [0.5527, -0.7207], [0.6152, -0.7207], [0.6836, -0.709], [0.7012, -0.6973], [0.7305, -0.668], [0.7695, -0.6191], [0.8105, -0.5527], [0.8691, -0.4316], [0.9043, -0.3496], [0.9336, -0.2695], [0.957, -0.1875], [0.9805, -0.0664], [0.998, 0.1035], [1.0, 0.1543], [0.9941, 0.2422], [0.9824, 0.3027], [0.9629, 0.3613], [0.9453, 0.3926], [0.9258, 0.4141], [0.9004, 0.4316], [0.875, 0.4375], [0.7871, 0.4336], [0.6074, 0.416], [0.3125, 0.3789], [0.0508, 0.3418], [0.0273, 0.3477], [-0.0195, 0.373], [-0.082, 0.4141], [-0.2832, 0.5332], [-0.3848, 0.5996], [-0.4004, 0.6133], [-0.5156, 0.6914], [-0.5703, 0.7168], [-0.5957, 0.7227], [-0.627, 0.7227], [-0.6484, 0.7148], [-0.6934, 0.6875]];
const BOW_H = {"b16": 1, "n": 220, "x0": -1.0, "x1": 1.0, "y0": 0.728515625, "y1": -0.7265625, "h": ""};
function buildE() {
  const grp = new THREE.Group();
  const FZ = .08, BZ = -.08;
  // the ribbon is twisted: both faces bend the same way, and the front dips further where the glitter bands are,
  // so those corners (upper left wing, lower right wing) are thinner
  const bend = (x, y) => .07 * x * y;
  const thin = (x, y) => Math.min(0, .1 * x * y);
  const frontX = (x, y) => bend(x, y) + thin(x, y);
  // a channel crosses the waist on the back; a small bridge in the middle covers the thread tunnel
  const CH = { cx: .07, cy: 0, ang: 1.43, w: .26, d: .085 };
  const groove = (x, y) => {
    const dx = x - CH.cx, dy = y - CH.cy;
    const v = -dx * Math.sin(CH.ang) + dy * Math.cos(CH.ang), hw = CH.w / 2, av = Math.abs(v);
    const edge = Math.min(1, Math.max(0, (hw - av) / .03));
    return CH.d * edge * edge * (3 - 2 * edge) * (1 - .3 * Math.pow(Math.min(1, av / hw), 2));
  };
  const backX = (x, y) => bend(x, y) + groove(x, y);
  const fm = bowMat(tex(TEX.eFrontBase), loader.load(TEX.eFiber), loader.load(TEX.eMask));
  fm.side = THREE.DoubleSide;
  const front = new THREE.Mesh(cloverRelief(BOW_H, FZ, .1, frontX), fm);
  front.onBeforeRender = (r, s, cam) => { fm.userData.uMV.value.setFromMatrix4(new THREE.Matrix4().multiplyMatrices(cam.matrixWorldInverse, front.matrixWorld)); };
  grp.add(front);
  // back photo was mirrored and lined up with the front outline beforehand, so plain UVs here
  const backMat = photoMat(tex(TEX.eBack), { roughness: .22, clearcoat: 1, clearcoatRoughness: .05, side: THREE.DoubleSide });
  grp.add(new THREE.Mesh(cloverRelief(BOW_H, BZ, -.06, backX), backMat));
  // side walls that follow the twist
  const pos = [], idx = [], n = BOW_OUT.length;
  BOW_OUT.forEach(([x, y]) => { pos.push(x, y, FZ + frontX(x, y) + .002, x, y, BZ + bend(x, y) - .002); });
  for (let i = 0; i < n; i++) { const j = (i + 1) % n; idx.push(2 * i, 2 * j, 2 * i + 1, 2 * j, 2 * j + 1, 2 * i + 1); }
  const wg = new THREE.BufferGeometry(); wg.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); wg.setIndex(idx); wg.computeVertexNormals();
  grp.add(new THREE.Mesh(wg, new THREE.MeshPhysicalMaterial({ color: 0x5a2e18, roughness: .25, clearcoat: 1, clearcoatRoughness: .06, envMapIntensity: .6, side: THREE.DoubleSide })));
  // bridge over the channel
  const backAt = (x, y) => BZ - .06 + bend(x, y);
  const hw = CH.w / 2 + .025, H = CH.d;
  const br = new THREE.Shape();
  br.moveTo(-hw, 0); br.lineTo(-hw, H); br.lineTo(hw, H); br.lineTo(hw, 0);
  br.lineTo(hw - .045, 0); br.lineTo(hw - .045, H * .35); br.quadraticCurveTo(0, H * .8, -hw + .045, H * .35); br.lineTo(-hw + .045, 0); br.closePath();
  const bg = new THREE.ExtrudeGeometry(br, { depth: .16, bevelEnabled: true, bevelThickness: .01, bevelSize: .01, bevelSegments: 3, curveSegments: 8 });
  bg.rotateX(-Math.PI / 2); bg.translate(0, -.08, 0); bg.rotateZ(CH.ang - Math.PI / 2);
  bg.translate(CH.cx, CH.cy, backAt(CH.cx, CH.cy) + CH.d);
  const bp = bg.attributes.position, buv = bg.attributes.uv;
  for (let i = 0; i < bp.count; i++) buv.setXY(i, bp.getX(i) / 2 + .5, bp.getY(i) / 2 + .5);
  grp.add(new THREE.Mesh(bg, backMat));
  return grp;
}
viewer(document.getElementById('cv'), buildE, 'v');
})();
